            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 120:
                    strong_bids.append(bid)
                elif bid >= 70:
                    moderate_bids.append(bid)

