        if moderate_prev > 0:
            bid = moderate_prev + 4.0
        else:
            bid = 72.0
        if supply_tight:
            bid += 6.0
        if highest_prev >= 120 and hp > 3:
            bid = min(bid, 88.0)
        return float(min(budget, bid))

    if supply_loose and hp >= 7:
        return float(min(budget, 24.0))

    if supply_tight:
        if moderate_prev > 0:
            bid = moderate_prev + 3.0
        else:
            bid = 68.0
        if highest_prev >= 120:
            bid = min(bid, 82.0)
        return float(min(budget, bid))

    if moderate_prev > 0:
        bid = moderate_prev + 1.5
        if highest_prev >= 120:
            bid = min(bid, 78.0)
        bid = max(52.0, bid)
        return float(min(budget, bid))

    base = 48.0
    if day >= 8:
        base = 58.0
    return float(min(budget, base))

